export type WorkspaceOperation = { operation_id: string, generation: number, sequence: number, session_id: string, plan: WorkspaceSetupPlan, state: WorkspaceOperationState, step: WorkspaceOperationStep, workspace_id: string | null, tab_id: string | null, pane_id: string | null, companion_id: string | null, owned_resources: Array<WorkspaceOwnedResource>, error: ErrorResponse | null, resume_allowed: boolean, cancel_requested: boolean, updated_at: string, };

export type ExtensionKind = "context" | "review";

export type DetectionConfidence = "verified_launch" | "verified_process" | "candidate" | "none" | "unsupported";

export type ContextRootKind = "repository" | "companion" | "folder";

export type ContextRoot = { root_id: string, kind: ContextRootKind, label: string, path: string, repository_id: string, checkout_path: string, companion_id: string | null, };

export type PanePresentation = { session_id: string, pane_id: string, terminal_id: string, binding_id: string, extension: ExtensionKind | null,
/**
 * Eligible automatic replacement, distinct from detected extension identity.
 */
renderer: ExtensionKind | null, confidence: DetectionConfidence, reason: string, roots: Array<ContextRoot>, default_root_id: string | null,
/**
 * Installed file-viewer support can open a fresh, source-pane-derived
 * Folder root. This remains distinct from Cockpit companion Context.
 */
can_open_files: boolean,
/**
 * The only Folder root accepted by `ContextLaunchRequest` when opening
 * files from the current source pane.
 */
files_root_id: string | null, can_open_context: boolean,
/**
 * Reviewr is installed/enabled at this endpoint and the current pane can
 * launch it only from an authorized primary repository checkout.
 */
can_open_review: boolean, diagnostics: Array<ProjectDiagnostic>, };

export type ContextDirectoryRequest = { binding_id: string, root_id: string, path: string, offset?: number, revision?: string, };

export type ContextEntryKind = "directory" | "file" | "symlink" | "other";

export type ContextEntry = { entry_id: string, name: string, path: string | null, kind: ContextEntryKind, bytes: number | null, revision: string, refusal: string | null, };

export type ContextDirectory = { binding_id: string, root_id: string, path: string, entries: Array<ContextEntry>, truncated: boolean, revision?: string, next_offset?: number, total_entries?: number, diagnostics: Array<ProjectDiagnostic>, };

export type ContextDocumentRequest = { binding_id: string, root_id: string, path: string, expected_revision: string | null, offset?: number, };

export type ContextDocument = { binding_id: string, root_id: string, path: string, revision: string, content_hash: string | null, bytes: number, media_type: string, text: string | null, truncated: boolean, offset?: number, next_offset?: number, total_bytes?: number | null, line_offset?: number, diagnostics: Array<ProjectDiagnostic>, };

export type ContextMediaRequest = { binding_id: string, root_id: string, path: string, expected_revision: string | null, };

export type ContextMedia = { binding_id: string, root_id: string, path: string, revision: string, content_hash: string, bytes: number, mime_type: string, width: number, height: number, data_base64: string, };

export type ContextSplitDirection = "right" | "down";

export type ContextLaunchRequest = { pane_id: string, binding_id: string, root_id: string, direction: ContextSplitDirection, };

export type ReviewLaunchRequest = { pane_id: string, binding_id: string,
/**
 * Opaque repository identity resolved from the authoritative source
 * pane's Git checkout at the launch boundary.
 */
repository_id: string, direction: ContextSplitDirection, };

export type CommentRequestScope = { binding_id: string, client_id: string, };

export type CommentOwner = { session_id: string, pane_id: string, terminal_id: string, source_kind: ExtensionKind,
/**
 * Companion identity for Context; a separate review identity for Review.
 */
source_id: string, };

export type CommentLocation = { workspace_id: string, tab_id: string, };

export type CommentAttachment = { owner: CommentOwner, location: CommentLocation, binding_id: string, client_id: string, };

export type CommentFileRef = { review?: CommentReviewRef, root_id: string, path: string, absolute_path: string, revision: string, content_hash: string | null, };

export type CommentSourceState = "current" | "changed" | "missing" | "unavailable";

export type CommentReviewRef = { review_id: string, generation: number, file_id: string, side: ReviewSide, };

export type CommentAnchor = { "kind": "whole_file" } | { "kind": "lines", start_line: number, end_line: number,
/**
 * Exact physical source lines, retaining CRLF/LF and a missing final newline.
 */
selected_lines: Array<string>, };

export type CommentDraft = { draft_id: string, file_ref: CommentFileRef, anchor: CommentAnchor, comment_text: string, source_state: CommentSourceState, updated_at: string, };

export type CommentBatch = { batch_id: string, generation: number, owner: CommentOwner, last_known_location: CommentLocation,
/**
 * Derived from fresh runtime proof; never persisted as an active attachment.
 */
live_attachment: CommentAttachment | null, drafts: Array<CommentDraft>, updated_at: string, };

export type CommentBatchSummary = { batch_id: string, generation: number, owner: CommentOwner, last_known_location: CommentLocation, draft_count: number, updated_at: string, };

export type CommentBatchList = { attachment: CommentAttachment, batches: Array<CommentBatchSummary>, truncated: boolean, };

export type CommentBatchRequest = { scope: CommentRequestScope,
/**
 * None finds this pane's existing batch or returns an unpersisted empty batch.
 */
batch_id: string | null, };

export type CommentBatchMutation = { scope: CommentRequestScope, batch_id: string, expected_generation: number, };

export type CommentCapture = { review?: CommentReviewRef, root_id: string, path: string, expected_revision: string,
/**
 * Both null means whole-file; otherwise both are inclusive physical line numbers.
 */
start_line: number | null, end_line: number | null, };

export type CommentUpsertRequest = { batch: CommentBatchMutation,
/**
 * None creates a draft with capture; editing changes text, not captured source.
 */
draft_id: string | null, capture: CommentCapture | null, comment_text: string, };

export type CommentRemoveRequest = { batch: CommentBatchMutation, draft_id: string, };

export type CommentPreviewRequest = { batch: CommentBatchMutation, retain_stale_excerpts: boolean, };

export type CommentPreview = { batch_id: string, generation: number, payload: string, payload_bytes: number, framed_bytes: number, limit_bytes: number, sanitized_controls: number, stale_draft_ids: Array<string>, exportable: boolean, reason: string | null, };

export type CommentPasteTarget = { endpoint_identity: string, session_id: string, workspace_id: string, tab_id: string, pane_id: string, terminal_id: string,
/**
 * Current agent name from Herdr, for target selection only.
 */
agent_label: string,
/**
 * Opaque fingerprint built from current terminal and agent identity evidence.
 */
agent_fingerprint: string, };

export type CommentPasteState = "pending" | "accepted" | "rejected" | "outcome_unknown";

export type CommentPastePrepareRequest = { batch: CommentBatchMutation, retain_stale_excerpts: boolean, };

export type CommentPastePrepareResponse = { batch_id: string, generation: number, payload_hash: string, payload_bytes: number, framed_bytes: number, limit_bytes: number, targets: Array<CommentPasteTarget>,
/**
 * Recent durable receipts for this batch; pending records are recovered as outcome-unknown.
 */
receipts: Array<CommentPasteReceipt>, paste_available: boolean, reason: string | null, };

export type CommentPasteSendRequest = { batch: CommentBatchMutation, target: CommentPasteTarget, expected_payload_hash: string, retain_stale_excerpts: boolean,
/**
 * Stable across duplicate transport delivery of the same user action.
 */
operation_id: string,
/**
 * Host/client request correlation. It is recorded but never used as a lease.
 */
request_id: string,
/**
 * Required only when the user consciously retries an outcome-unknown receipt.
 */
acknowledge_duplicate_risk: boolean, };

export type CommentPasteMarkPastedRequest = { batch: CommentBatchMutation, operation_id: string, };

export type CommentPasteReceipt = { operation_id: string, request_id: string, batch_id: string, batch_generation: number, payload_hash: string, target: CommentPasteTarget, state: CommentPasteState, sent_draft_ids: Array<string>, created_at: string, completed_at: string | null, message: string | null,
/**
 * The user explicitly resolved this prior outcome after inspection.
 */
user_confirmed: boolean, };

export type WorkspaceTeardownAction = "close_space" | "remove_owned_worktree" | "reconcile_remove_outcome" | "remove_orphaned_companion" | "forget_association";

export type WorkspaceTeardownOwnership = "owned_created" | "borrowed_opened" | "foreign" | "unknown";

export type WorkspaceTeardownDirtyState = "clean" | "dirty" | "unknown";

export type WorkspaceTeardownWorkspaceState = "live" | "missing" | "ambiguous";

export type WorkspaceTeardownCompanionState = "owned" | "missing" | "foreign" | "ambiguous";

export type WorkspaceTeardownPreviewRequest = { workspace_id: string, };

export type WorkspaceTeardownExecuteRequest = { operation_id: string, workspace_id: string, expected_endpoint_identity: string, expected_checkout_path: string, action: WorkspaceTeardownAction, confirmation: string, };

export type WorkspaceTeardownPreview = { operation_id: string, workspace_id: string, endpoint_identity: string, repository_key: string | null, repository_root: string | null, checkout_path: string, ownership: WorkspaceTeardownOwnership, workspace_state: WorkspaceTeardownWorkspaceState, companion_state: WorkspaceTeardownCompanionState, is_linked_worktree: boolean, dirty_state: WorkspaceTeardownDirtyState, companion_path: string | null, allowed_actions: Array<WorkspaceTeardownAction>, blockers: Array<string>, warnings: Array<string>, required_confirmation: string | null, };

export type WorkspaceTeardownOutcome = "completed" | "outcome_unknown" | "orphaned_companion" | "retained";

export type WorkspaceTeardownResult = { operation_id: string, workspace_id: string, action: WorkspaceTeardownAction, outcome: WorkspaceTeardownOutcome, message: string, };

export type WorkspaceTeardownRecoveryState = "pending" | "outcome_unknown" | "orphaned_companion";

export type WorkspaceTeardownRecovery = { operation_id: string, workspace_id: string, checkout_path: string, state: WorkspaceTeardownRecoveryState, };

export type WorkspaceTeardownRecoveryList = { recoveries: Array<WorkspaceTeardownRecovery>, };

export type SourceCapability = "issue" | "issue_comments" | "review" | "wiki";

export type SourceFreshness = "fresh" | "changed" | "unknown" | "unavailable" | "conflict";

export type SourceMaterializationStatus = "materialized" | "unchanged" | "conflict" | "unsupported" | "failed";

export type SourceImportRequest = { binding_id: string, root_id: string, provider_id: string, artifact_url: string,
/**
 * Reference traversal is opt-in because following even same-repository
 * links can produce surprising context expansion.
 */
hydrate_references: boolean, };

export type SourceListRequest = { binding_id: string, root_id: string, };

export type SourceRefreshRequest = { binding_id: string, root_id: string, source_id: string, hydrate_references: boolean, };

export type SourceEntry = { source_id: string, provider_id: string, provider_instance: string, resource_type: string, canonical_id: string, title: string, source_url: string | null, original_url: string | null, source_revision: string | null, content_hash: string, freshness: SourceFreshness, status: SourceMaterializationStatus, relative_path: string | null, };

export type SourceImportResponse = { binding_id: string, root_id: string, entries: Array<SourceEntry>, diagnostics: Array<ProjectDiagnostic>, };

export type ReviewSide = "old" | "new";

export type ReviewComparison = "all_local" | "staged" | "unstaged" | "branch" | "untracked";

export type ReviewFileStatus = "added" | "modified" | "deleted" | "renamed" | "copied" | "untracked" | "binary" | "mode_only" | "submodule" | "unreadable";

export type ReviewDiffLineKind = "context" | "added" | "deleted";

export type ReviewSnapshotRequest = { binding_id: string, repository_id: string, comparison: ReviewComparison,
/**
 * Required only for branch comparison; resolved to an immutable commit.
 */
base_ref: string | null, };

export type ReviewChangedFile = { file_id: string,
/**
 * All-local preserves each staged/unstaged/untracked anchor separately.
 */
comparison: ReviewComparison, status: ReviewFileStatus, old_path: string | null, new_path: string | null, binary: boolean,
/**
 * Exact parsed line counts, absent when the file diff is incomplete or
 * non-textual rather than misleadingly reported as zero.
 */
additions: number | null, deletions: number | null, summary: string, old_revision: string | null, new_revision: string | null, };

export type ReviewSnapshot = { binding_id: string, session_id: string, pane_id: string, review_id: string, generation: number, repository_id: string, checkout_path: string,
/**
 * Stable direct-checkout identity shared with Review comment batches.
 */
source_id: string, comparison: ReviewComparison, base_revision: string | null, head_revision: string | null, index_revision: string, worktree_revision: string, files: Array<ReviewChangedFile>, truncated: boolean, diagnostics: Array<ProjectDiagnostic>, };

export type ReviewFileRequest = { binding_id: string, review_id: string, generation: number, file_id: string,
/**
 * Optional continuation for a large immutable source side. When absent,
 * the response contains the normal bounded preview for both sides.
 */
source_side: ReviewSide | null, source_offset: number,
/**
 * Exact revision identity expected for a continuation. The server
 * rejects a page when the selected file no longer has this identity.
 */
source_revision: string | null, };

export type ReviewDiffLine = { kind: ReviewDiffLineKind, old_line: number | null, new_line: number | null,
/**
 * Exact line bytes decoded as UTF-8 only for textual Git diff output.
 */
text: string, };

export type ReviewHunk = { old_path: string | null, new_path: string | null, old_start: number, new_start: number, lines: Array<ReviewDiffLine>, };

export type ReviewFileDiff = { binding_id: string, session_id: string, pane_id: string, review_id: string, generation: number, file: ReviewChangedFile, hunks: Array<ReviewHunk>,
/**
 * Bounded immutable text retained for old/new review-side capture and
 * expansion of unchanged lines. None means binary, unreadable, or capped.
 */
old_source: string | null, new_source: string | null, old_source_hash: string | null, new_source_hash: string | null,
/**
 * Byte ranges represented by old_source/new_source. A truncated source
 * can be continued with ReviewFileRequest.source_side/source_offset.
 */
old_source_offset: number, new_source_offset: number, old_source_total_bytes: number | null, new_source_total_bytes: number | null, old_total_lines: number | null, new_total_lines: number | null, old_source_truncated: boolean, new_source_truncated: boolean, truncated: boolean, diagnostics: Array<ProjectDiagnostic>, };

export type ContextSnapshotRequest = { binding_id: string, root_id: string, repository_id: string, mode: ContextSnapshotMode, };

export type ContextSnapshotResponse = { binding_id: string, root_id: string, repository_id: string,
/**
 * A path relative to the authorized companion root.
 */
snapshot_path: string, generation: string, mode: ContextSnapshotMode, copy_mode: ContextSnapshotCopyMode, files: number, bytes: number, source_head: string | null, dirty: boolean, diagnostics: Array<ProjectDiagnostic>, };

export type ContextSnapshotMode = "working_tree";

export type ContextSnapshotCopyMode = "reflink" | "copy" | "mixed";

export type ContextSearchRequest = { binding_id: string, root_id: string, query: string, request_generation: number, offset?: number, revision?: string, };

export type ContextSearchResult = { path: string, line: number, excerpt: string, revision: string, };

export type ContextSearchResponse = { binding_id: string, root_id: string, query: string, request_generation: number, results: Array<ContextSearchResult>, scanned_files: number, truncated: boolean, revision?: string, next_offset?: number, partial_reason?: string, };

export type ContextKnownRevision = { path: string, revision: string, };

export type ContextInvalidationState = "changed" | "missing" | "unavailable";

export type ContextInvalidation = { path: string, state: ContextInvalidationState, revision: string | null, };

export type ContextInvalidationRequest = { binding_id: string, root_id: string, request_generation: number, known: Array<ContextKnownRevision>, };

export type ContextInvalidationResponse = { binding_id: string, root_id: string, request_generation: number, invalidations: Array<ContextInvalidation>, truncated: boolean, };
